#!/usr/bin/env python3
"""Build the bilingual Khamrah pilot. Preserve existing SEO head metadata.
Photography is deliberately gated by assets/academy-media.json.
"""
from pathlib import Path
import json,re,html
R=Path(__file__).resolve().parents[1]
media=json.loads((R/'assets/academy-media.json').read_text())
for lang in ('es','en'):
 es=lang=='es'
 def t(a,b): return a if es else b
 base=f'/perfume-bronx/{lang}/'
 target=R/lang/'academy/khamrah/index.html'
 head=target.read_text().split('</head>')[0]
 head=re.sub(r'<link rel="stylesheet" href="/perfume-bronx/assets/academy-(?:deck|cinema).css">','',head)
 head+='<link rel="stylesheet" href="/perfume-bronx/assets/academy-cinema.css"></head>'
 chapters=t(['Esencia','Notas','Arquitectura','Evolución','Contraste','Tu elección','Explorar'],['Essence','Notes','Architecture','Evolution','Contrast','Your choice','Explore'])
 def scene(n,kind,title,body,art):
  return f'<section id="scene-{n}" class="cinema-scene scene-{kind}" aria-labelledby="title-{n}"><div class="scene-copy"><p class="eyebrow">{n:02d} / 07 — {chapters[n-1]}</p><h2 id="title-{n}" tabindex="-1">{title}</h2>{body}</div>{art}</section>'
 def p(s): return '<p>'+s+'</p>'
 def link(url,label,cl='cinema-link'):return f'<a class="{cl}" href="{url}">{label}</a>'
 hero=('<figure class="scent-sculpture" aria-label="'+t('Interpretación gráfica del perfil aromático; no representa el frasco','Graphic interpretation of the scent profile; not a bottle depiction')+'"><div class="scent-orbit orbit-one"></div><div class="scent-orbit orbit-two"></div><div class="scent-orbit orbit-three"></div><div class="scent-core"><span>LATTAFA</span><strong>KHAMRAH</strong><em>'+t('Especias. Dulzor. Calidez.','Spice. Sweetness. Warmth.')+'</em></div><figcaption>'+t('ESTUDIO OLFATIVO · ORIGINAL','OLFACTORY STUDY · ORIGINAL')+'</figcaption></figure>')
 m=media['khamrah']
 if m.get('approved'):
  if not m.get('rights_evidence') or not m.get('path') or not (R/m['path']).is_file():raise ValueError('Approved media requires local file and rights evidence')
  hero=f'<figure class="product-stage"><img src="/perfume-bronx/{html.escape(m["path"])}" alt="Lattafa Khamrah original" width="720" height="900" fetchpriority="high"></figure>'
 s=[]
 s.append(scene(1,'hero',t('La calidez<br>tiene capas.','Warmth<br>has layers.'),p(t('Una entrada especiada. Un corazón dulce. Una base de vainilla y maderas. Explora Khamrah original en siete escenas.','A spicy opening. A sweet heart. A vanilla and woody base. Explore original Khamrah in seven scenes.'))+link('#scene-2',t('Comenzar el recorrido ↗','Begin the journey ↗'))+p('<small>'+t('60–90 segundos · A tu ritmo','60–90 seconds · At your pace')+'</small>'),hero))
 notes=t([('Canela','Un matiz especiado para imaginar la primera impresión.','spice'),('Dátiles','Un acorde que sugiere dulzor de fruta madura.','date'),('Vainilla','Una referencia dulce dentro de una base compleja.','vanilla')],[('Cinnamon','A spicy facet to picture the opening impression.','spice'),('Dates','An accord suggesting the sweetness of ripe fruit.','date'),('Vanilla','A sweet reference within a complex base.','vanilla')])
 art='<div class="note-gallery">'+''.join(f'<details class="note-study"><summary><span class="note-drawing drawing-{k}" aria-hidden="true"></span><span><small>0{i+1}</small><strong>{name}</strong><span class="note-hint">'+t('Explorar +','Explore +')+f'</span></span></summary><p>{desc}</p></details>' for i,(name,desc,k) in enumerate(notes))+'</div>'
 s.append(scene(2,'notes',t('Aprende a<br>imaginar un aroma.','Learn to<br>imagine a scent.'),p(t('Toca cada estudio para descubrir su papel. Las notas describen impresiones olfativas; no son una lista de ingredientes de la fórmula.','Open each study to discover its role. Notes describe scent impressions; they are not a formula ingredient list.')),art))
 tiers=t([('Salida','Bergamota · canela · nuez moscada','La primera impresión: un contraste cítrico y especiado.'),('Corazón','Acorde de dátiles · muguete · praliné · nardo','El centro del relato reúne facetas dulces y florales.'),('Fondo','Tonka tostada · benjuí de Laos · mirra · Akigalawood · vainilla · madera ambarada','La base reúne facetas resinosas, amaderadas y dulces. No predice horas de duración.')],[('Top','Bergamot · cinnamon · nutmeg','The opening impression: citrus and spicy facets.'),('Heart','Dates accord · lily of the valley · praline · tuberose','The centre of the story brings sweet and floral facets together.'),('Base','Roasted tonka · Laos benzoin · myrrh · Akigalawood · vanilla · amber wood','The base brings resinous, woody and sweet facets together. It does not predict hours of wear.')])
 art='<div class="pyramid-lab"><div class="pyramid-controls" aria-label="'+t('Niveles de la pirámide','Pyramid levels')+'">'+''.join(f'<button type="button" data-tier="{i}" aria-expanded="true" aria-controls="tier-{i}"><span>0{i+1}</span><strong>{label}</strong></button>' for i,(label,_,__) in enumerate(tiers))+'</div><div class="tier-readings">'+''.join(f'<div id="tier-{i}" class="tier-reading"><h3>{label}</h3><p>{notes}</p><p class="tier-explain">{desc}</p></div>' for i,(label,notes,desc) in enumerate(tiers))+'</div><button type="button" class="text-button" data-reset hidden>'+t('Ver todos los niveles ↺','See all levels ↺')+'</button></div>'
 s.append(scene(3,'pyramid',t('Tres niveles.<br>Una composición.','Three levels.<br>One composition.'),p(t('Selecciona una capa para acercarte a sus notas. Vuelve a la vista completa para ver cómo se relacionan.','Select a layer to move closer to its notes. Return to the full view to see how they relate.')),art))
 art='<div class="evolution-story">'+''.join(f'<article><span class="timeline-dot" aria-hidden="true"></span><small>0{i+1}</small><h3>{label}</h3><p>{desc}</p></article>' for i,(label,_,desc) in enumerate(tiers))+'</div>'
 s.append(scene(4,'evolution',t('El tiempo cambia<br>la percepción.','Time changes<br>perception.'),p(t('Recorre la evolución. Las fases se solapan: no son un reloj ni una promesa de rendimiento. La piel, la aplicación y el entorno cambian lo que percibes.','Explore the evolution. Phases overlap: they are neither a clock nor a performance promise. Skin, application and surroundings change what you perceive.')),art))
 art='<div class="contrast-pair"><article><small>01 / KHAMRAH</small><h3>'+t('Dulzor<br>especiado','Spiced<br>sweetness')+'</h3><p>'+t('Canela · dátiles · praliné','Cinnamon · dates · praline')+'</p><span class="profile-line" aria-hidden="true"></span></article><article><small>02 / YARA PINK</small><h3>'+t('Dulzor<br>floral','Floral<br>sweetness')+'</h3><p>'+t('Orquídea · acorde tropical · vainilla','Orchid · tropical accord · vanilla')+'</p><span class="profile-line" aria-hidden="true"></span></article></div>'
 s.append(scene(5,'contrast',t('Dos formas<br>de ser dulce.','Two ways<br>to be sweet.'),p(t('No se trata de cuál es mejor, sino de qué perfil te atrae. Esta comparación interpreta las notas publicadas; no representa una prueba en piel.','The question is which profile appeals to you. This comparison interprets published notes; it is not a skin test.'))+link(base+'compare/yara-khamrah-asad/',t('Abrir la comparación completa ↗','Open the full comparison ↗')),art))
 q=t('¿Qué te gustaría explorar primero?','What would you like to explore first?')
 options=t([('Un perfil dulce y especiado','Khamrah es una opción para explorar: sus notas combinan canela, dátiles y praliné. Confirma tu preferencia probándolo cuando sea posible.'),('Un perfil dulce y floral','Explora Yara Pink: sus notas florales y tropicales ofrecen otro punto de partida. Dulce no significa que ambos huelan igual.'),('Todavía no lo sé','Compara primero las familias y pregunta por la posibilidad de probarlos. No necesitas elegir a ciegas.')],[('A sweet and spicy profile','Khamrah is a profile to explore: its notes combine cinnamon, dates and praline. Confirm your preference by trying it when possible.'),('A sweet and floral profile','Explore Yara Pink: floral and tropical notes offer another starting point. Sweet does not mean both smell alike.'),('I am not sure yet','Compare the families and ask whether trying them is possible. You do not need to choose blindly.')])
 art='<div class="preference-lab"><h3>'+q+'</h3>'+''.join(f'<details class="choice"><summary>{a}<span aria-hidden="true">↗</span></summary><p>{b}</p></details>' for a,b in options)+'</div>'
 s.append(scene(6,'question',t('Tu gusto<br>marca el camino.','Your taste<br>sets the direction.'),p(t('No hay una respuesta correcta en una preferencia. Abre una opción para entender qué explorar después.','There is no correct answer to a preference. Open an option to understand what to explore next.')),art))
 art='<div class="closing-card"><small>'+t('ANTES DE ELEGIR','BEFORE YOU CHOOSE')+'</small><h3>'+t('Pregunta.<br>Compara.<br>Decide.','Ask.<br>Compare.<br>Decide.')+'</h3><p>'+t('Khamrah original y Khamrah Qahwa son variantes diferentes. Confirma el nombre y la presentación.','Original Khamrah and Khamrah Qahwa are different variants. Confirm the name and presentation.')+'</p></div>'
 body=p(t('Consulta disponibilidad y pregunta si se puede coordinar una prueba presencial en tu zona. Confirma dirección, tarifa y plazo antes de comprar.','Check availability and ask whether an in-person trial can be arranged in your area. Confirm address, fee and timing before buying.'))+link(base+'products/khamrah/',t('Consultar Khamrah ↗','Ask about Khamrah ↗'))+p(t('Delivery gratis desde 2 unidades dentro de la cobertura confirmada. Una unidad lleva tarifa por confirmar.','Free delivery from 2 units within confirmed coverage. Delivery for one unit requires a confirmed fee.'))
 s.append(scene(7,'closing',t('Del perfil<br>a tu elección.','From profile<br>to your choice.'),body,art))
 nav='<nav class="chapter-nav" aria-label="'+t('Escenas','Scenes')+'">'+''.join(link(f'#scene-{i+1}',f'<span>{i+1:02d}</span> {c}','chapter-link') for i,c in enumerate(chapters))+'</nav>'
 controls='<nav class="cinema-controls" hidden aria-label="'+t('Controles de la presentación','Presentation controls')+'"><button type="button" data-prev aria-label="'+t('Escena anterior','Previous scene')+'">←</button><span data-counter role="status" aria-live="polite"></span><div class="cinema-progress" aria-hidden="true"><span></span></div><button type="button" data-next aria-label="'+t('Escena siguiente','Next scene')+'">→</button><button type="button" data-motion aria-pressed="true">'+t('Movimiento','Motion')+'</button><button type="button" data-reading aria-pressed="false">'+t('Leer todo','Read all')+'</button></nav>'
 footer='<footer class="cinema-footer"><p>'+t('Notas:','Notes:')+' <a href="https://lattafa.com/product/khamrah/">Lattafa Khamrah</a> · <a href="https://lattafa.com/product/yara/">Lattafa Yara</a>. '+t('Interpretación educativa. No es una prueba independiente.','Educational interpretation. Not an independent wear test.')+'</p>'+link(base+'academy/',t('← Volver a la Academia','← Back to Academy'))+'<button type="button" class="btn share-button" hidden>'+t('Compartir','Share')+'</button><p id="share-status" role="status" aria-live="polite"></p></footer>'
 target.write_text(head+'<body class="academy-cinema"><a class="skip" href="#content">'+t('Saltar al contenido','Skip to content')+'</a><main id="content" class="cinema-shell" data-cinema="khamrah"><header class="cinema-header">'+link(base+'academy/','OUD BRONX <span>ACADEMY</span>','cinema-brand')+link('/perfume-bronx/'+('en' if es else 'es')+'/academy/khamrah/',t('English','Español'),'language-link')+'</header><div class="cinema-intro"><p class="eyebrow">'+t('EL ATELIER DEL AROMA','THE SCENT ATELIER')+'</p><h1>Khamrah <em>Original</em></h1><p>'+t('LATTAFA · ESPECIAS & DULZOR','LATTAFA · SPICE & SWEETNESS')+'</p></div>'+nav+'<div class="cinema-stage">'+''.join(s)+'</div>'+controls+footer+'</main><script src="/perfume-bronx/assets/share.js" defer></script><script src="/perfume-bronx/assets/academy-cinema.js" defer></script></body></html>\n')
print('Built Khamrah ES/EN; approved product photography:',bool(media['khamrah']['approved']))
